// 文件: app/page.tsx (Server Component)
import { Suspense } from 'react';
import ClientComponent from './ClientComponent';

// 异步数据获取函数
async function fetchUsers() {
  // 模拟从 API 获取数据，使用 fetch 选项设置缓存策略
  const res = await fetch('https://jsonplaceholder.typicode.com/users', {
    next: { revalidate: 3600 } // 每小时重新验证一次
  });
  if (!res.ok) {
    throw new Error('Failed to fetch users');
  }
  return res.json();
}

// 服务器组件，支持 async/await
export default async function UsersPage() {
  const users = await fetchUsers();
  return (
    <div>
      <h1>User List (Server Rendered)</h1>
      {/* 使用 Suspense 包裹客户端组件，提供加载状态 */}
      <Suspense fallback={<div>Loading user interactions...</div>}>
        <ClientComponent initialUsers={users} />
      </Suspense>
    </div>
  );
}

// 文件: app/ClientComponent.tsx (Client Component)
'use client'; // 标记为客户端组件

import { useState } from 'react';

// 客户端组件，处理交互
export default function ClientComponent({ initialUsers }: { initialUsers: any[] }) {
  const [searchTerm, setSearchTerm] = useState('');
  // 过滤用户列表
  const filteredUsers = initialUsers.filter(user =>
    user.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div>
      <input
        type="text"
        placeholder="Search users..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <ul>
        {filteredUsers.map(user => (
          <li key={user.id}>{user.name} - {user.email}</li>
        ))}
      </ul>
    </div>
  );
}

